	@Test
	void nestedInterruptedIOExceptionAfterOwnedShutdownStampRemainsAWorkerFailure() {
		long failuresBefore = LmdbNativeParallelPipelines.WORKER_FAILURES.get();
		NativeCancellationToken token = new NativeCancellationToken();
		LmdbNativeParallelPipelines.ParallelRowCursor cursor = cursor(token);
		Object owner = new Object();
		AtomicReference<Object> pendingInterruptionOwner = new AtomicReference<>();
		QueryExecutionContext.WorkerScope scope = new QueryExecutionContext.WorkerScope() {
			@Override
			public QueryExecutionContext.Activation activate() {
				Thread worker = Thread.currentThread();
				pendingInterruptionOwner.set(owner);
				worker.interrupt();
				return () -> {
					if (Thread.currentThread() == worker) {
						Thread.interrupted();
					}
					pendingInterruptionOwner.set(null);
				};
			}

			@Override
			public Object consumeInterruptionOwner() {
				return pendingInterruptionOwner.getAndSet(null);
			}

			@Override
			public boolean ownsCancellation(Object candidate) {
				return candidate == owner;
			}

		};
		IOException nestedReadFailure = new IOException("foreign nested read failed",
				new InterruptedException("nested read was independently interrupted"));

		Throwable closeFailure;
		try (QueryExecutionContext.Activation replay = QueryExecutionContext.activateReplaySafepoint(() -> {
		}, () -> scope)) {
			cursor.runTask(() -> {
				assertThat(pendingInterruptionOwner.get()).isSameAs(owner);
				assertThat(Thread.currentThread().isInterrupted()).isTrue();
				throw nestedReadFailure;
			}, null, mock(NativeLmdbQuerySource.ParallelSource.class));
		} finally {
			closeFailure = catchThrowable(cursor::close);
		}

		assertThat(cursor.failure.get())
				.as("an unrelated nested IOException must remain visible after a stamped shutdown interrupt")
				.isSameAs(nestedReadFailure);
		assertThat(closeFailure).isInstanceOf(QueryEvaluationException.class).hasCause(nestedReadFailure);
		assertThat(LmdbNativeParallelPipelines.WORKER_FAILURES.get())
				.as("only the owner's cancellation signal may be retired as control flow")
				.isEqualTo(failuresBefore + 1);
	}

